```text
export function ocrBuffer(png, opts) {
  const dir = mkdtempSync(join(tmpdir(), 'cue-ocr-'));
  const f = join(dir, 'shot.png');
  writeFileSync(f, png);
  return ocrFile(f, opts);
```

