export function health(hwnd) {
  const h = Number(hwnd);
  const out = Buffer.alloc(8);
  const t0 = Date.now();
  const ok = SendMessageTimeoutW(h, 0, 0, 0, 0x0002, 800, out);
  return { hung: IsHungAppWindow(h), responds: Boolean(ok), ms: Date.now() - t0 };
}
